INSERT INTO edition_feature_results (scope, edition_id, feature_id, name, description, created_at, updated_at, source_resp, source_id, source_revision, source_name)
SELECT DISTINCT 'editions', edition_id, 'm_classifier', 'Subject Categories', 'Printed non-reprint V9 classification preview with accepted EIP and light review overrides.', '2026-06-06T00:00:00Z', '2026-06-06T00:00:00Z', 'v9_preview', NULL, 'printed_non_reprints_v9_reviewed_2026_06_06', 'edition classification v9 reviewed preview'
FROM temp_edition_v9_values
WHERE 1
ON CONFLICT(scope, edition_id, feature_id) DO UPDATE SET
    name = excluded.name,
    description = excluded.description,
    source_resp = excluded.source_resp,
    source_id = excluded.source_id,
    source_revision = excluded.source_revision,
    source_name = excluded.source_name,
    updated_at = excluded.updated_at;

DELETE FROM edition_feature_result_values
WHERE scope = 'editions'
  AND feature_id = 'm_classifier'
  AND edition_id IN (SELECT DISTINCT edition_id FROM temp_edition_v9_values);

INSERT INTO edition_feature_result_values (scope, edition_id, feature_id, surface)
SELECT 'editions', edition_id, 'm_classifier', surface
FROM temp_edition_v9_values;

DROP TABLE temp_edition_v9_values;

COMMIT;
